# Vault breakdown census: category totals + duplicate tonnage
# Counts and sizes only; prints no file contents.
import os
import sys

ROOT = r"D:\Opawota_Poto"
BIG = 1 << 20  # 1 MiB threshold for duplicate analysis

categories = {
    "node_modules": 0, ".git": 0, ".trash": 0, "__pycache__": 0,
    "venv/.venv": 0, ".obsidian": 0, ".smart-env": 0, ".letta": 0,
    "drive-download-*": 0, "takeout*": 0, "backup/clone folders": 0,
    "agent dotfolders": 0,
}
cat_files = {k: 0 for k in categories}
cat_bytes = {k: 0 for k in categories}

total_files = 0
total_bytes = 0
dup_index = {}   # (name, size) -> [paths] for files >= 1MiB
big_files = 0
big_bytes = 0

AGENT_DOTS = {".chrome-cdp-profile", ".cortexweaver", ".heimdall", ".shrimp", ".smart-env"}

def classify(dpath, dname):
    n = dname.lower()
    if dname == "node_modules":
        return "node_modules"
    if dname == ".git":
        return ".git"
    if dname == ".trash":
        return ".trash"
    if dname == "__pycache__":
        return "__pycache__"
    if dname in ("venv", ".venv"):
        return "venv/.venv"
    if dname == ".obsidian":
        return ".obsidian"
    if dname == ".letta" or dname == ".letta" :
        return ".letta"
    if dname in AGENT_DOTS:
        return "agent dotfolders"
    if n.startswith("drive-download-"):
        return "drive-download-*"
    if n.startswith("takeout"):
        return "takeout*"
    if "backup" in n or n.endswith("-001") or "backup" in n:
        return "backup/clone folders"
    return None

skip_names = {"node_modules", ".git", ".trash", "__pycache__", "venv", ".venv"}

for dirpath, dirnames, filenames in os.walk(ROOT):
    # classify this directory's own name once, inherited from parent marker
    # we use a per-path active category stack via dirpath prefix checks
    pass

# simpler: recursive walk with pruning
def walk(dpath, active):
    global total_files, total_bytes, big_files, big_bytes
    try:
        entries = list(os.scandir(dpath))
    except OSError:
        return
    for e in entries:
        try:
            if e.is_dir(follow_symlinks=False):
                cat = classify(dpath, e.name)
                new_active = cat if cat is not None else active
                if cat is not None:
                    # count the whole subtree under its category
                    sub_f, sub_b = subtree(e.path)
                    cat_files[cat] += sub_f
                    cat_bytes[cat] += sub_b
                    continue  # do not descend further
                walk(e.path, active)
            elif e.is_file(follow_symlinks=False):
                sz = e.stat(follow_symlinks=False).st_size
                total_files += 1
                total_bytes += sz
                if sz >= BIG:
                    big_files += 1
                    big_bytes += sz
                    key = (e.name.lower(), sz)
                    dup_index.setdefault(key, []).append(e.path)
        except OSError:
            continue

def subtree(p):
    f = b = 0
    for dp, dns, fns in os.walk(p):
        for fn in fns:
            try:
                sz = os.stat(os.path.join(dp, fn)).st_size
                f += 1
                b += sz
            except OSError:
                f += 1
        # count dirs not needed
    return f, b

walk(ROOT, None)

redundant_copies = 0
redundant_bytes = 0
top_groups = []
for (name, sz), paths in dup_index.items():
    n = len(paths)
    if n > 1:
        redundant_copies += n - 1
        redundant_bytes += (n - 1) * sz
        top_groups.append(((n - 1) * sz, n, sz, name))
top_groups.sort(reverse=True)

print("TOTAL files (excl. categorized subtrees): %d" % total_files)
print("TOTAL bytes (excl. categorized subtrees): %.2f MB" % (total_bytes / 1048576))
print()
for k in categories:
    print("%-24s %8d files  %12.2f MB" % (k, cat_files[k], cat_bytes[k] / 1048576))
print()
print("files >= 1 MiB: %d, their bytes: %.2f MB" % (big_files, big_bytes / 1048576))
print("duplicate groups (name+size, >=1MiB): %d" % sum(1 for v in dup_index.values() if len(v) > 1))
print("redundant copies: %d, redundant bytes: %.2f MB" % (redundant_copies, redundant_bytes / 1048576))
print()
print("Top 12 duplicate groups by wasted bytes:")
for wasted, n, sz, name in top_groups[:12]:
    print("  %10.2f MB wasted  x%d  (%.2f MB each)  %s" % (wasted / 1048576, n, sz / 1048576, name[:70]))

